class Solution {
    vector<char> cover(const string&s,const string&p){int n=s.size(),m=p.size();vector<int> pi(m);for(int i=1,j=0;i<m;i++){while(j&&p[i]!=p[j])j=pi[j-1];if(p[i]==p[j])j++;pi[i]=j;}vector<int> diff(n+1);for(int i=0,j=0;i<n;i++){while(j&&s[i]!=p[j])j=pi[j-1];if(s[i]==p[j])j++;if(j==m){diff[i-m+1]++;diff[i+1]--;j=pi[j-1];}}vector<char> ans(n);int run=0;for(int i=0;i<n;i++){run+=diff[i];ans[i]=run>0;}return ans;}
public:int countCells(vector<vector<char>>& grid,string pattern){int m=grid.size(),n=grid[0].size();string h,v;for(auto&r:grid)for(char c:r)h+=c;for(int j=0;j<n;j++)for(int i=0;i<m;i++)v+=grid[i][j];auto a=cover(h,pattern),b=cover(v,pattern);int ans=0;for(int i=0;i<m;i++)for(int j=0;j<n;j++)ans+=a[i*n+j]&&b[j*m+i];return ans;}
};
